/*
QUESTION:
Implement the Trie class, which supports insertion, search, and startsWith operations.

Approach:
- Create a TrieNode class with an array of child nodes, each representing a letter.
- The Trie class maintains a root TrieNode.
- For insertion, traverse the trie, creating new nodes as necessary for each character.
- For search, traverse the trie, checking if nodes exist for each character and if the final node is marked as a complete word.
- For startsWith, traverse the trie similarly to search, but don't require the final node to be marked as a complete word.

Complexity Analysis:
- Insertion, search, and startsWith operations take O(L) time, where L is the length of the word or prefix.
- Space complexity is O(N * M), where N is the number of words and M is the average length of the words.

CODE:-
*/

class TrieNode{
public:
    TrieNode* child[26];
    bool isWord;

    TrieNode(){
        this->isWord = false;
        for(int i=0; i<26; i++){
            this->child[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(string word) {
        TrieNode* curr = root;
        for(int i=0; i<word.size(); i++){
            int ltr = word[i] - 'a';
            if(!curr->child[ltr])
                curr->child[ltr] = new TrieNode();
            curr = curr->child[ltr];
        }
        curr->isWord = true;
    }

    bool search(string word) {
        TrieNode* curr = root;
        for(int i=0; i<word.size(); i++){
            int ltr = word[i]-'a';
            if(!curr->child[ltr]) return false;
            curr = curr->child[ltr];
        }
        return curr && curr->isWord;
    }

    bool startsWith(string prefix) {
        TrieNode* curr = root;
        for(int i=0; i<prefix.size(); i++){
            int ltr = prefix[i]-'a';
            if(!curr->child[ltr]) return false;
            curr = curr->child[ltr];
        }
        return curr;
    }
};

/*
QUESTION:
Ninja has to implement a data structure "TRIE" from scratch. Implement the functions as follows:
1) Trie(): Initializes the trie object.
2) insert("WORD"): Inserts the string "WORD" into the trie.
3) countWordsEqualTo("WORD"): Returns how many times the string "WORD" is present in the trie.
4) countWordsStartingWith("PREFIX"): Returns how many words in the trie have the string "PREFIX" as a prefix.
5) erase("WORD"): Deletes one occurrence of the string "WORD" from the trie.

Approach:
- Create a TrieNode class with an array of child nodes, each representing a letter.
- Maintain the count of words with a specific prefix (cntPre) and the count of words (cntWord) at each node.
- Implement insert, countWordsEqualTo, countWordsStartingWith, and erase functions using TrieNode operations.

Complexity Analysis:
- All operations take O(L) time, where L is the length of the word or prefix.
- Space complexity is O(N * M), where N is the number of words and M is the average length of the words.
*/

class TrieNode {
public:
    int cntWord, cntPre;
    TrieNode* child[26];

    TrieNode() {
        this->cntPre = 0;
        this->cntWord = 0;
        for (int i = 0; i < 26; i++) {
            this->child[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(string &word) {
        TrieNode* curr = root;
        for (int i = 0; i < word.size(); i++) {
            int ltr = word[i] - 'a';
            if (!curr->child[ltr])
                curr->child[ltr] = new TrieNode();
            curr = curr->child[ltr];
            curr->cntPre++;
        }
        curr->cntWord++;
    }

    int countWordsEqualTo(string &word) {
        TrieNode* curr = root;
        for (int i = 0; i < word.size(); i++) {
            int ltr = word[i] - 'a';
            if (!curr->child[ltr])
                return 0;
            curr = curr->child[ltr];
        }
        return curr->cntWord;
    }

    int countWordsStartingWith(string &prefix) {
        TrieNode* curr = root;
        for (int i = 0; i < prefix.size(); i++) {
            int ltr = prefix[i] - 'a';
            if (!curr->child[ltr])
                return 0;
            curr = curr->child[ltr];
        }
        return curr->cntPre;
    }

    void erase(string &word) {
        TrieNode* curr = root;
        for (int i = 0; i < word.size(); i++) {
            int ltr = word[i] - 'a';
            curr = curr->child[ltr];
            curr->cntPre--;
        }
        curr->cntWord--;
    }
};

/*
QUESTION:
Ninja developed a fascination for arrays and strings, so this time his teacher gave him an array of strings 'A' of size 'N'. Each element of this array is a string. A string is called a complete string if every prefix of this string is also present in the array 'A'. Ninja is challenged to find the longest complete string in the array 'A'. If there are multiple strings with the same length, return the lexicographically smallest one, and if no string exists, return "None".

Example:
N = 4
A = ["ab", "abc", "a", "bp"]
Explanation:
- Only prefix of the string "a" is "a", which is present in array 'A'. So, it is one of the possible strings.
- Prefixes of the string "ab" are "a" and "ab", both of which are present in array 'A'. So, it is one of the possible strings.
- Prefixes of the string "bp" are "b" and "bp". "b" is not present in array 'A'. So, it cannot be a valid string.
- Prefixes of the string "abc" are "a", "ab", and "abc", all of which are present in array 'A'. So, it is one of the possible strings.
- We need to find the maximum length string, so "abc" is the required string.

Approach:
- Create a Trie data structure to store the strings in the array 'A'.
- Insert all the strings into the Trie.
- Iterate through each string in array 'A':
  - Check if the string is a valid complete string using the Trie.
  - If it is valid, update the answer string based on the length and lexicographical order.

Complexity Analysis:
- Inserting each string into the Trie takes O(N*K) time and space, where N is the number of strings and K is the average length of strings.
- Validating each string takes O(K) time.
- The overall time complexity is O(N*K) and the space complexity is O(N*K), where N is the number of strings and K is the average length of strings.
*/

class TrieNode {
public:
    TrieNode* children[26];
    bool end;

    TrieNode() {
        this->end = false;
        for (int i = 0; i < 26; i++) {
            this->children[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(string& word) {
        TrieNode* curr = root;
        int n = word.size();
        for (int i = 0; i < n; i++) {
            int key = word[i] - 'a';
            if (curr->children[key] == NULL) {
                curr->children[key] = new TrieNode();
            }
            curr = curr->children[key];
        }
        curr->end = true;
    }

    bool isvalid(string& word) {
        TrieNode* curr = root;
        int n = word.size();
        for (int i = 0; i < n; i++) {
            int key = word[i] - 'a';
            if (curr->children[key] == NULL || curr->children[key]->end == false) {
                return false;
            }
            curr = curr->children[key];
        }
        return curr != NULL && curr->end;
    }
};

string completeString(int n, vector<string>& a) {

    Trie tr;

    for (auto it : a) {
        tr.insert(it);
    }

    string ans = "";

    for (auto it : a) {
        if (tr.isvalid(it)) {
            if (ans.size() < it.size())
                ans = it;
            else if (ans.size() == it.size() && it < ans)
                ans = it;
        }
    }
    if (ans.size() == 0)
        return "None";
    return ans;

}

/*
QUESTION:
Given a string of length N of lowercase alphabet characters. Implement the function countDistinctSubstring() to return the count of total distinct substrings of the given string.

Approach:
- Create a Trie data structure to efficiently store and count distinct substrings.
- For each character in the string, insert its suffixes into the Trie, and each insertion increases the count of distinct substrings.
- Return the total count of distinct substrings.

Complexity Analysis:
- Inserting each substring into the Trie takes O(N) time and O(N) space.
- Overall time complexity is O(N^2) since there are O(N^2) substrings in total.
- Space complexity is O(N) to store the Trie.
*/

class TrieNode {
public:
    TrieNode* child[26];

    TrieNode() {
        for (int i = 0; i < 26; i++) {
            this->child[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;
    Trie() {
        root = new TrieNode();
    }

    void insert(string word, int& cnt) {
        TrieNode* curr = root;
        for (int i = 0; i < word.size(); i++) {
            int ltr = word[i] - 'a';
            if (!curr->child[ltr]) {
                cnt++;
                curr->child[ltr] = new TrieNode();
            }
            curr = curr->child[ltr];
        }
    }
};

int countDistinctSubstring(string s) {
    int cnt = 0;
    Trie* tr = new Trie();
    for (int i = 0; i < s.size(); i++) {
        tr->insert(s.substr(i), cnt);
    }
    return cnt + 1; // Adding 1 for the empty string itself
}

/*
QUESTION:
You are given six positive integers: 'a', 'b', 'c', 'd', 'e', and 'f'.
You will be given three functions: 'getXOR', 'getBit', and 'setBit'.
Your task is to do the following:
1. In the function 'getXOR', you will be given two parameters, 'a', and 'b'. Your task is to return the XOR of 'a' and 'b'.
2. In the function 'getBit', you will be given two parameters, 'c' and 'd'. Your task is to return 1 if the 'c'th bit of 'd' is set. Otherwise, return 0.
3. In the function 'setBit', you will be given two parameters, 'e' and 'f'. Your task is to set the 'e'th bit in 'f' if it is not set. At last, return the integer 'f'. The expected time complexity is 'O(1)', and the expected space complexity is 'O(1').

CODE:

Approach:
1. For the 'getXOR' function, simply use the XOR (^) operator to get the XOR of 'a' and 'b'.
2. For the 'getBit' function, use the right shift (>>) and bitwise AND (&) operators to check if the 'c'th bit of 'd' is set or not.
3. For the 'setBit' function, use the bitwise OR (|) operator and left shift (<<) to set the 'e'th bit in 'f'.

Complexity Analysis:
- All three functions have a time complexity of O(1) as they involve simple bitwise operations.
- All three functions have a space complexity of O(1) as they do not require additional memory allocation.
*/

int getXOR(int a, int b) {
    return a ^ b;
}

int getBit(int c, int d) {
    return (d >> c) & 1;
}

int setBit(int e, int f) {
    return f | (1 << e);
}

/*
QUESTION:
Given an integer array nums, return the maximum result of nums[i] XOR nums[j], where 0 <= i <= j < n.

Example:

Input: nums = [3,10,5,25,2,8]
Output: 28
Explanation: The maximum result is 5 XOR 25 = 28.

Approach:
1. Create a Trie data structure that stores binary representations of the given numbers.
2. For each number, insert its binary representation into the Trie.
3. For each number, find the maximum XOR that can be obtained with any other number using the Trie.
   - Traverse the Trie for each bit of the number and try to find a bit in the other number's binary representation that gives the maximum XOR.
   - If a complementary bit is found, set the corresponding bit in the result.
4. Return the maximum XOR found.

Complexity Analysis:
- The Trie insertion and search operations both take O(32) time since we are dealing with 32 bits (maximum). Therefore, the time complexity of the solution is O(n * 32), which simplifies to O(n).
- The space complexity is also O(n) since we are storing the Trie.

CODE:
*/

class TrieNode {
public:
    TrieNode* child[2];

    TrieNode() {
        for(int i = 0; i < 2; i++) {
            this->child[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(int num) {
        TrieNode* curr = root;
        for(int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if(!curr->child[bit]) {
                curr->child[bit] = new TrieNode();
            }
            curr = curr->child[bit];
        }
    }

    int findMax(int num) {
        TrieNode* curr = root;
        int maxNum = 0;
        for(int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if(curr->child[1 - bit]) {
                maxNum = maxNum | (1 << i);
                curr = curr->child[1 - bit];
            } else {
                curr = curr->child[bit];
            }
        }
        return maxNum;
    }
};

class Solution {
public:
    int findMaximumXOR(vector<int>& nums) {
        Trie* tr = new Trie();
        for(auto i : nums) {
            tr->insert(i);
        }
        int ans = 0;
        for(auto i : nums) {
            int temp = tr->findMax(i);
            ans = max(ans, temp);
        }
        return ans;
    }
};
